#include <stdio.h>
int main() {
    int i, n, f;
    printf("n = ");
    scanf("%d", &n);
    if (n < 0) {
        printf("Invalid: %d\n", n);
        n = -1;
    } else {
        f = 1;
        for (i = 1; i <= n; i++) {
            f *= i;
        }
        printf("%d! = %d\n", n, f);
    }
    return n;
}

